//It is for viewing the rule isOR setup when we hover the mouse on the active rebate header and line rule column
public static void initPricingAttributeValue(GUPPricingAttributeValueTmp pricingAttributeValue, GUPPricingRuleCondition ruleCond, GUPPricingAttributeLink link)
{
    next initPricingAttributeValue(pricingAttributeValue, ruleCond, link);
    pricingAttributeValue.METisOR = ruleCond.METisOR;
}
